themeCSS:
.node.api rect, .node.api polygon, .node.api path, .node.api circle, .node.api ellipse { fill: #4051b5; stroke: #8c9eff; }
.node.api .nodeLabel, .node.api .label span, .node.api .label p, .node.api span { color: #ffffff; }
.node.api text { fill: #ffffff; }
.node.api line { stroke: #8c9eff; }
.node.model rect, .node.model polygon, .node.model path, .node.model circle, .node.model ellipse { fill: #16393a; stroke: #4db6ac; }
.node.model .nodeLabel, .node.model .label span, .node.model .label p, .node.model span { color: #dcf3f0; }
.node.model text { fill: #dcf3f0; }
.node.model line { stroke: #4db6ac; }
.node.ext rect, .node.ext polygon, .node.ext path, .node.ext circle, .node.ext ellipse { fill: #2a2e3b; stroke: #8a90a6; }
.node.ext .nodeLabel, .node.ext .label span, .node.ext .label p, .node.ext span { color: #dadde8; }
.node.ext text { fill: #dadde8; }
.node.ext line { stroke: #8a90a6; }
.node.human rect, .node.human polygon, .node.human path, .node.human circle, .node.human ellipse { fill: #3d3020; stroke: #ffb74d; }
.node.human .nodeLabel, .node.human .label span, .node.human .label p, .node.human span { color: #fff1db; }
.node.human text { fill: #fff1db; }
.node.human line { stroke: #ffb74d; }
.node.ok rect, .node.ok polygon, .node.ok path, .node.ok circle, .node.ok ellipse { fill: #1c3a25; stroke: #66bb6a; }
.node.ok .nodeLabel, .node.ok .label span, .node.ok .label p, .node.ok span { color: #e3f4e4; }
.node.ok text { fill: #e3f4e4; }
.node.ok line { stroke: #66bb6a; }
.node.bad rect, .node.bad polygon, .node.bad path, .node.bad circle, .node.bad ellipse { fill: #401f24; stroke: #ef6b6b; }
.node.bad .nodeLabel, .node.bad .label span, .node.bad .label p, .node.bad span { color: #ffe5e5; }
.node.bad text { fill: #ffe5e5; }
.node.bad line { stroke: #ef6b6b; }
.node.note rect, .node.note polygon, .node.note path, .node.note circle, .node.note ellipse { fill: #1e2129; stroke: #5d6584; }
.node.note .nodeLabel, .node.note .label span, .node.note .label p, .node.note span { color: #aab0c4; }
.node.note text { fill: #aab0c4; }
.node.note line { stroke: #5d6584; }
.node.note rect, .node.note polygon, .node.note path { stroke-dasharray: 5 4; }
.cluster-label span p, .cluster-label .nodeLabel p { background-color: #1e2129 !important; padding: 0 6px; }
text.messageText, text.loopText, text.loopText tspan { paint-order: stroke fill; stroke: #1e2129; stroke-width: 10px; stroke-linejoin: round; }
.node circle.state-start { fill: #8f98bd; stroke: #8f98bd; }
.node > g.outer-path:not(.label-container) > path { fill: #1e2129; stroke: #8f98bd; }
.node > g.outer-path:not(.label-container) > g > path { fill: #8f98bd; stroke: #8f98bd; }
.edgeLabel, .edgeLabel p, .labelBkg { background-color: #1e2129; }
.edgeLabel rect { opacity: 1; fill: #1e2129; }
.edgeLabel span, .edgeLabel p { color: #aab0c4; }
.edgeLabel { font-size: 14px; }
.nodeLabel small, .label small { font-size: 13px; opacity: 0.82; }
.node.list .label div { text-align: left !important; }
.node.list .nodeLabel, .node.list p { font-size: 15px; }
.node.note .nodeLabel, .node.note p { font-size: 14px; }
